	selftest_white  = color.RGBA{255, 255, 255, 255}
	selftest_gray   = color.RGBA{64, 64, 64, 255}
	selftest_green  = color.RGBA{0, 255, 0, 255}
	selftest_red    = color.RGBA{255, 0, 0, 255}
