func selftest_main() {
	// ジョイスティックのセンター位置は起動直後に測る (触らないこと)
	joy := badge.NewJoystick()
	joy.Calibrate(300 * time.Millisecond)

	time.Sleep(200 * time.Millisecond)
	println("selftest start, id", badge.SerialNumber())

	display := badge.NewDisplay()
	fb := badge.NewFramebuffer(display)
	w, h := fb.Size()

	// LCD の全面表示。この間にほかのデバイスを初期化する
	fb.FillScreen(selftest_red)
	fb.Display()
	leds := badge.NewLEDs()
	leds.SetBrightness(32)
	sw1, sw2 := badge.NewButtons()
	time.Sleep(300 * time.Millisecond)

	fb.FillScreen(selftest_green)
	fb.Display()
	sensor := badge.NewSensor()
	badge.ConfigureGroveI2C()
	rx := badge.NewIRReceiver()
	rx.SetCommandHandler(selftest_onReceive)
	tx, txErr := badge.NewIRTransmitter()
	if txErr != nil {
		println("ir tx init:", txErr.Error())
	}
	time.Sleep(300 * time.Millisecond)

	fb.FillScreen(selftest_blue)
	fb.Display()
	time.Sleep(300 * time.Millisecond)

	var (
		chkSW1   = selftest_check{name: "SW1"}
		chkSW2   = selftest_check{name: "SW2"}
		chkBtn   = selftest_check{name: "JOY button"}
		chkUp    = selftest_check{name: "JOY up"}
		chkDown  = selftest_check{name: "JOY down"}
		chkLeft  = selftest_check{name: "JOY left"}
		chkRight = selftest_check{name: "JOY right"}
		chkAHT   = selftest_check{name: "AHT21B"}
		chkIR    = selftest_check{name: "IR loopback"}
		chkAudio = selftest_check{name: "AUDIO"}
	)
	checks := []*selftest_check{&chkSW1, &chkSW2, &chkBtn, &chkUp, &chkDown, &chkLeft, &chkRight, &chkAHT, &chkIR, &chkAudio}

	audio, audioErr := badge.NewAudio()
	var tone *badge.ToneGenerator
	if audioErr != nil {
		println("audio init:", audioErr.Error())
	} else {
		chkAudio.pass()
		tone = badge.NewToneGenerator(audio)
		for _, n := range []uint32{523, 659, 784} {
			tone.Play(n, 80, selftest_volume)
		}
		tone.Stop()
	}
	beep := func(freq uint32) {
		if tone != nil {
			tone.Play(freq, 60, selftest_volume)
			tone.Stop()
		}
	}

	ledIdx := 0
	lastLED := time.Time{}

	lastSensor := time.Time{}
	sensorText := "reading..."

	lastScan := time.Time{}
	groveText := "scanning..."
	groveColor := selftest_yellow

	lastTX := time.Time{}
	irCmd := uint8(0)
	irSent := 0
	irBack := 0
	irOther := "" // 自分以外から受信したコード
	lastSeq := selftest_rxSeq.Get()

	prev1, prev2, prevBtn := false, false, false
	allOK := false

	for {
		frameStart := time.Now()
		now := frameStart

		// ---- 入力 ----
		x, y, btn := joy.Read()
		p1, p2 := sw1.Pressed(), sw2.Pressed()
		if p1 {
			chkSW1.pass()
		}
		if p2 {
			chkSW2.pass()
		}
		if btn {
			chkBtn.pass()
		}
		const edge = 900
		if y > edge {
			chkUp.pass()
		}
		if y < -edge {
			chkDown.pass()
		}
		if x < -edge {
			chkLeft.pass()
		}
		if x > edge {
			chkRight.pass()
		}

		// 押した瞬間にビープを鳴らす (ボタンごとに音程を変える)
		if p1 && !prev1 {
			beep(880)
		}
		if p2 && !prev2 {
			beep(660)
		}
		if btn && !prevBtn {
			beep(440)
		}
		prev1, prev2, prevBtn = p1, p2, btn

		// ---- LED ----
		if now.Sub(lastLED) >= selftest_ledInterval {
			lastLED = now
			ledIdx = (ledIdx + 1) % len(selftest_ledColors)
			c := selftest_ledColors[ledIdx].c
			leds.WriteColors([]color.RGBA{c, c})
		}

		// ---- 温湿度センサー ----
		if now.Sub(lastSensor) >= time.Second {
			lastSensor = now
			if err := sensor.Read(); err != nil {
				sensorText = "read error"
			} else {
				t, rh := sensor.DeciCelsius(), sensor.DeciRelHumidity()
				sensorText = selftest_deci(t) + "C " + selftest_deci(rh) + "%"
				if t > -200 && t < 800 && rh > 0 && rh <= 1000 {
					chkAHT.pass()
				} else {
					sensorText += " ?"
				}
			}
		}

		// ---- Grove I2C ----
		if now.Sub(lastScan) >= 2*time.Second {
			lastScan = now
			found := badge.ScanI2C(badge.GroveI2C)
			s := ""
			for _, addr := range found {
				s += "0x" + selftest_hex8(uint8(addr)) + " "
			}
			if s == "" {
				s = "none"
				groveColor = selftest_white
			} else {
				groveColor = selftest_cyan
			}
			if s != groveText {
				println("grove i2c:", s)
			}
			groveText = s
		}

		// ---- 赤外線 ----
		if seq := selftest_rxSeq.Get(); seq != lastSeq {
			lastSeq = seq
			repeat := selftest_rxFlags.Get()&uint16(irremote.DataFlagIsRepeat) != 0
			addr, cmd := selftest_rxAddress.Get(), selftest_rxCommand.Get()
			if !repeat && addr == selftest_irAddress && cmd == uint16(irCmd) {
				irBack++
				chkIR.pass()
			} else if !repeat {
				irOther = selftest_hex8(uint8(addr)) + ":" + selftest_hex8(uint8(cmd))
				println("ir rx: addr", addr, "cmd", cmd, "code 0x"+selftest_hex32(selftest_rxCode.Get()))
			}
		}
		if tx != nil && now.Sub(lastTX) >= time.Second {
			lastTX = now
			irCmd++
			irSent++
			tx.SendNEC(selftest_irAddress, irCmd)
		}

		// ---- 判定 ----
		if !allOK {
			allOK = true
			for _, c := range checks {
				allOK = allOK && c.ok
			}
			if allOK {
				println("ALL OK")
				if tone != nil {
					for _, n := range []uint32{784, 1047} {
						tone.Play(n, 100, selftest_volume)
					}
					tone.Stop()
				}
			}
		}

		// ---- 描画 ----
		fb.FillScreen(selftest_black)
		tinyfont.WriteLine(fb, selftest_font, selftest_labelX, 18, "SELF TEST #"+badge.SerialNumber(), selftest_white)

		row := int16(selftest_firstY)
		label := func(s string) {
			tinyfont.WriteLine(fb, selftest_font, selftest_labelX, row, s, selftest_white)
		}

		label("SW1")
		selftest_text(fb, selftest_valueX, row, selftest_pressedText(p1), selftest_state(chkSW1.ok))
		row += selftest_rowH

		label("SW2")
		selftest_text(fb, selftest_valueX, row, selftest_pressedText(p2), selftest_state(chkSW2.ok))
		row += selftest_rowH

		label("JOY")
		cx := selftest_text(fb, selftest_valueX, row, "B", selftest_state(chkBtn.ok))
		cx = selftest_text(fb, cx+6, row, "U", selftest_state(chkUp.ok))
		cx = selftest_text(fb, cx+6, row, "D", selftest_state(chkDown.ok))
		cx = selftest_text(fb, cx+6, row, "L", selftest_state(chkLeft.ok))
		selftest_text(fb, cx+6, row, "R", selftest_state(chkRight.ok))
		row += selftest_rowH

		label("LED")
		lc := selftest_ledColors[ledIdx]
		fb.FillRectangle(selftest_valueX, row-13, 24, 14, lc.c)
		selftest_text(fb, selftest_valueX+30, row, lc.name, selftest_white)
		row += selftest_rowH

		label("AHT")
		selftest_text(fb, selftest_valueX, row, sensorText, selftest_state(chkAHT.ok))
		row += selftest_rowH

		label("GROVE")
		selftest_text(fb, selftest_valueX, row, groveText, groveColor)
		row += selftest_rowH

		label("IR")
		irText := selftest_itoa(irBack) + "/" + selftest_itoa(irSent)
		if tx == nil {
			irText = "tx init error"
		}
		cx = selftest_text(fb, selftest_valueX, row, irText, selftest_state(chkIR.ok))
		if irOther != "" {
			selftest_text(fb, cx+8, row, "ext "+irOther, selftest_cyan)
		}
		row += selftest_rowH

		label("AUDIO")
		if audioErr != nil {
			selftest_text(fb, selftest_valueX, row, "init error", selftest_red)
		} else {
			selftest_text(fb, selftest_valueX, row, "ok (listen)", selftest_green)
		}

		// ジョイスティックの位置
		fb.FillRectangle(selftest_padX, selftest_padY, selftest_padSize, selftest_padSize, selftest_gray)
		fb.FillRectangle(selftest_padX+selftest_padSize/2, selftest_padY, 1, selftest_padSize, selftest_black)
		fb.FillRectangle(selftest_padX, selftest_padY+selftest_padSize/2, selftest_padSize, 1, selftest_black)
		nx := selftest_padX + int16((x+1000)*(selftest_padSize-6)/2000)
		ny := selftest_padY + int16((1000-y)*(selftest_padSize-6)/2000)
		dot := selftest_white
		if btn {
			dot = selftest_red
		}
		fb.FillRectangle(nx, ny, 6, 6, dot)

		// 最下行に総合判定
		if allOK {
			fb.FillRectangle(0, h-24, w, 24, selftest_green)
			selftest_text(fb, selftest_labelX, h-6, "ALL OK", selftest_black)
		} else {
			left := 0
			for _, c := range checks {
				if !c.ok {
					left++
				}
			}
			selftest_text(fb, selftest_labelX, h-6, selftest_itoa(left)+" check(s) left", selftest_yellow)
		}
		fb.Display()

		// 約 30fps に揃える
		if d := 33*time.Millisecond - time.Since(frameStart); d > 0 {
			time.Sleep(d)
		}
	}
}

// text は (x, y) に文字列を描き、描いた文字列の右端の x を返す。
func selftest_text(fb *badge.Framebuffer, x, y int16, s string, c color.RGBA) int16 {
	tinyfont.WriteLine(fb, selftest_font, x, y, s, c)
	_, width := tinyfont.LineWidth(selftest_font, s)
	return x + int16(width)
}

// state は判定済みなら緑、未確認なら黄色を返す。
func selftest_state(ok bool) color.RGBA {
	if ok {
		return selftest_green
	}
	return selftest_yellow
}

func selftest_pressedText(p bool) string {
	if p {
		return "pressed"
	}
	return "-"
}

// deci は 1/10 単位の整数を "12.3" 形式の文字列にする。
func selftest_deci(v int32) string {
	neg := v < 0
	if neg {
		v = -v
	}
	s := selftest_itoa(int(v/10)) + "." + selftest_itoa(int(v%10))
	if neg {
		return "-" + s
	}
	return s
}

func selftest_itoa(v int) string {
	if v == 0 {
		return "0"
	}
	var buf [12]byte
	i := len(buf)
	for v > 0 {
		i--
		buf[i] = byte('0' + v%10)
		v /= 10
	}
	return string(buf[i:])
}

const selftest_hexDigits = "0123456789abcdef"

func selftest_hex8(v uint8) string {
	return string([]byte{selftest_hexDigits[v>>4], selftest_hexDigits[v&0xf]})
}

func selftest_hex32(v uint32) string {
	var b [8]byte
	for i := range b {
		b[i] = selftest_hexDigits[v>>(28-4*i)&0xf]
	}
	return string(b[:])
}
